FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state        : INT;
    prevOpenBtn  : BOOL;
    prevCloseBtn : BOOL;
END_VAR

openBtnRising  := openBtn AND NOT prevOpenBtn;
closeBtnRising := closeBtn AND NOT prevCloseBtn;

prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;

IF state = 0 AND NOT prevOpenBtn AND NOT prevCloseBtn THEN
    motorUp   := FALSE;
    motorDown := FALSE;
    errorFlag := FALSE;
END_IF

CASE TO_INT(state) OF
    0:
        motorUp   := FALSE;
        motorDown := FALSE;
        IF openBtnRising AND NOT openLimit THEN
            state := 1;
        ELSIF closeBtnRising AND NOT closeLimit THEN
            state := 2;
        END_IF

    1:
        motorUp   := TRUE;
        motorDown := FALSE;
        IF obstacle THEN
            state     := 3;
            errorFlag := TRUE;
            motorUp   := FALSE;
            motorDown := FALSE;
        ELSIF openLimit THEN
            state := 0;
        END_IF

    2:
        motorUp   := FALSE;
        motorDown := TRUE;
        IF obstacle THEN
            motorUp   := TRUE;
            motorDown := FALSE;
            IF openLimit THEN
                state := 0;
            ELSE
                state := 1;
            END_IF
        ELSIF closeLimit THEN
            state     := 0;
            motorUp   := FALSE;
            motorDown := FALSE;
        END_IF

    3:
        motorUp   := FALSE;
        motorDown := FALSE;
        IF openBtn AND closeBtn THEN
            state     := 0;
            errorFlag := FALSE;
        END_IF
END_CASE

motorUp   := TO_BOOL(state = 1);
motorDown := TO_BOOL(state = 2);
END_FUNCTION_BLOCK
